def build_guidance(english_codes):
    guides = basic_guides()
    technical = {'pf','dep','et','pa','vc','eu','mb','el','sn','cl'}
    experience = {'si','st','sw','wk','ot','ob','pr','me','to','rp','gr','gap','in','su','fa','ha','ch','pro','id','te','tc','cr','cs','cu','dt','lf','da'}
    for code,guide in guides.items():
        guide['kind'] = 'concept' if code in technical else 'hypothetical' if code in experience else 'approach'
        guide['refs'] = TOPIC_REFERENCES.get(code,[])
        guide['pressure'] = []
        guide['technicalVariants'] = TECHNICAL_VARIANTS.get(code,[])
        guide['companyExamples'] = COMPANY_EXAMPLES.get(code,{})
        if code in JAPANESE_EXAMPLES:
            guide['japaneseExample'] = JAPANESE_EXAMPLES[code]
        if code in english_codes:
            guide['englishExample'] = ENGLISH_EXAMPLES[code]
    for line in PRESSURE.strip().splitlines():
        code,question,answer,followup,followup_answer,adapt = line.split('|')
        guides[code.lower()]['pressure'].append(dict(question=question,answer=answer,followup=followup,
                                                    followupAnswer=followup_answer,adapt=adapt))
    return guides
